144		if _, err := s.Reserve(mxCommitOver, mxReqB, mxPartID, mxM-1, clk.expiry, clk.now); !errors.Is(err, ErrInsufficientStock) {
145			t.Fatalf("reserve M-1 over committable: got %v, want ErrInsufficientStock", err)
146		} else if errors.Is(err, ErrInvalidParam) {
147			t.Fatalf("reserve M-1: got %v, must not be ErrInvalidParam for a representable positive quantity", err)
148		}
149	
150		// 失败不生成承诺。
151		if _, err := s.Commitment(mxCommitOver); !errors.Is(err, ErrNotFound) {
152			t.Fatalf("rejected commitment %q exists: err=%v", mxCommitOver, err)
153		}
154		// 失败不改变原承诺的数量、归属与到期时刻。
155		assertMxFirstCommitment(t, s, clk)
156		// 查询仍只有先前的成功占用：实物 M、占用 M−2、可承诺 2，明细只有第一笔。
157		st = assertMxAccount(t, s, clk.now, mxM, mxM-2, 2)
158		if len(st.Details) != 1 || st.Details[0].CommitmentID != mxCommitFirst {
159			t.Fatalf("details after rejection = %+v, want only the first commitment", st.Details)
160		}
161	
162		// 失败请求的历史：本次库存不足记录保留拒绝前的真实账目（实物 M、占用
163		// M−2、可承诺 2），不是负数、零库存或失败之后的其他状态；资格为合格。
164		histB, err := s.RequestHistory(mxReqB)
