170		}
171		rec := histB[0]
172		if rec.Success || rec.Error != HistoryErrorInsufficientStock ||
173			rec.CommitID != mxCommitOver || rec.PartID != mxPartID || rec.Quantity != mxM-1 ||
174			!rec.Expiry.Equal(clk.expiry) || !rec.Now.Equal(clk.now) {
175			t.Fatalf("rejection record = %+v, want insufficient_stock for M-1", rec)
176		}
177		if rec.Eligibility == nil || !rec.Eligibility.Eligible || len(rec.Eligibility.Reasons) != 0 {
178			t.Fatalf("rejection record eligibility = %+v, want eligible", rec.Eligibility)
179		}
180		assertMxBasis(t, rec, mxM, mxM-2, 2)
181	
182		// 第三步：同一请求改用新承诺编号申请恰好 2 件，成功。
183		exact, err := s.Reserve(mxCommitExact, mxReqB, mxPartID, 2, clk.expiry, clk.now)
184		if err != nil {
185			t.Fatalf("reserve exact 2: %v", err)
186		}
187		if exact.Quantity != 2 || exact.Used != 0 || exact.Unused() != 2 || exact.RequestID != mxReqB {
188			t.Fatalf("exact reserve result = %+v, want quantity 2 unused for request b", exact)
189		}
190	
191		// 两笔有效承诺的未用数量合计为 M，实物库存仍为 M，可承诺数量为零。
192		st = assertMxAccount(t, s, clk.now, mxM, mxM, 0)
193		if len(st.Details) != 2 {
194			t.Fatalf("details = %+v, want two active commitments", st.Details)
195		}
196		unusedSum := 0
197		for _, d := range st.Details {
198			if d.Status != CommitmentActive || d.UsedQuantity != 0 {
199				t.Fatalf("detail = %+v, want active with used 0", d)
200			}
201			unusedSum += d.RemainingQuantity
202		}
203		if unusedSum != mxM {
204			t.Fatalf("unused sum = %d, want M = %d", unusedSum, mxM)
205		}
206	
207		// 第四步：可承诺数量已为零，再用新编号申请 1 件仍返回库存不足，
208		// 不能留下第三笔承诺。
209		if _, err := s.Reserve(mxCommitExtra, mxReqB, mxPartID, 1, clk.expiry, clk.now); !errors.Is(err, ErrInsufficientStock) {
210			t.Fatalf("reserve 1 after exhaustion: got %v, want ErrInsufficientStock", err)
211		}
212		if _, err := s.Commitment(mxCommitExtra); !errors.Is(err, ErrNotFound) {
213			t.Fatalf("rejected commitment %q exists: err=%v", mxCommitExtra, err)
214		}
215		st = assertMxAccount(t, s, clk.now, mxM, mxM, 0)
216		if len(st.Details) != 2 {
217			t.Fatalf("details after final rejection = %+v, want still two commitments", st.Details)
218		}
219		assertMxFirstCommitment(t, s, clk)
220	
221		// 成功记录的库存依据保留新增占用之前的数值：第一笔是实物 M、占用 0、
222		// 可承诺 M；恰好 2 件那笔是实物 M、占用 M−2、可承诺 2。失败记录同样
223		// 保留当次拒绝前的真实账目。
224		histA, err := s.RequestHistory(mxReqA)
225		if err != nil {
226			t.Fatalf("request a history: %v", err)
227		}
228		if len(histA) != 1 || !histA[0].Success || histA[0].Error != "" ||
229			histA[0].CommitID != mxCommitFirst || histA[0].Quantity != mxM-2 {
230			t.Fatalf("request a history = %+v, want single success of M-2", histA)
231		}
232		assertMxBasis(t, histA[0], mxM, 0, mxM)
233	
234		histB, err = s.RequestHistory(mxReqB)
235		if err != nil {
236			t.Fatalf("request b history: %v", err)
237		}
238		if len(histB) != 3 {
239			t.Fatalf("request b history length = %d, want 3 (fail, success, fail)", len(histB))
240		}
241		for i, rec := range histB {
242			if rec.Seq != i+1 {
243				t.Fatalf("record %d seq = %d, want %d", i, rec.Seq, i+1)
244			}
245		}
246		if histB[1].Success != true || histB[1].Error != "" ||
247			histB[1].CommitID != mxCommitExact || histB[1].Quantity != 2 {
248			t.Fatalf("second record = %+v, want success of exactly 2", histB[1])
249		}
250		assertMxBasis(t, histB[1], mxM, mxM-2, 2)
251		if histB[2].Success || histB[2].Error != HistoryErrorInsufficientStock ||
252			histB[2].CommitID != mxCommitExtra || histB[2].Quantity != 1 {
253			t.Fatalf("third record = %+v, want insufficient_stock for 1", histB[2])
254		}
255		assertMxBasis(t, histB[2], mxM, mxM, 0)
256	
257		// 按请求和按备件查看的成功承诺归属与数量一致。
258		viewA, err := s.RequestView(mxReqA, clk.now)
259		if err != nil {
260			t.Fatalf("request a view: %v", err)
261		}
262		if len(viewA.Commitments) != 1 || viewA.Commitments[0].CommitmentID != mxCommitFirst ||
263			viewA.Commitments[0].OriginalQuantity != mxM-2 || viewA.Commitments[0].RemainingQuantity != mxM-2 {
264			t.Fatalf("request a commitments = %+v, want the M-2 commitment", viewA.Commitments)
265		}
266		viewB, err := s.RequestView(mxReqB, clk.now)
267		if err != nil {
268			t.Fatalf("request b view: %v", err)
269		}
270		if len(viewB.Commitments) != 1 || viewB.Commitments[0].CommitmentID != mxCommitExact ||
271			viewB.Commitments[0].OriginalQuantity != 2 || viewB.Commitments[0].RemainingQuantity != 2 {
272			t.Fatalf("request b commitments = %+v, want the 2-unit commitment", viewB.Commitments)
273		}
274		byID := make(map[string]CommitmentDetail, len(st.Details))
275		for _, d := range st.Details {
276			byID[d.CommitmentID] = d
277		}
278		for _, view := range []*RequestView{viewA, viewB} {
279			for _, c := range view.Commitments {
280				d, ok := byID[c.CommitmentID]
281				if !ok || d.RequestID != c.RequestID || d.OriginalQuantity != c.OriginalQuantity ||
282					d.RemainingQuantity != c.RemainingQuantity || d.UsedQuantity != c.UsedQuantity {
283					t.Fatalf("request view %+v inconsistent with part detail %+v", c, d)
284				}
285			}
286		}
287	}
